$wms-header-height: 80px;
$wms-empty-message-custom:'There is no data to display.';
$wms-hover-color: #CDE6EB; 
$wms-hover-border: 2px solid #0f789b;
$wms-slideout-min-width: 328px;
/**
1. Content Header 
    1.1 Filter section
    1.2 Text Filter (Lot, Equipment, Carrier)
2. Left Sidebar 
    2.1 Dispatch List Label Region (Action Icon, Dispatch List Label, selected lot count)
    2.2 Dispatch Lot List
3. Working section 
    3.1 Equipment List section
    3.2 Collaspe Section
        3.2.1 Process Section
        3.2.2 Activity Collapse Section
            3.2.2.1 Activities List
            3.2.2.2 Collapse Icon section
    3.3 Comments Area
    3.4 Information Bar Area
4. Command Bar Content
    4.1 Slide Out Design
    4.2 Alert Message Slide Out
    4.3 Alert Message Content
    4.4 Lot Details Slide Out
    4.5 Online Traveler Slide Out
    4.6 WIP Failures Slide Out
    4.7 Equipment Info Slide Out
    4.9 SPC Chart
    4.10 Command Bar Overview
**/

.wms-main-layout {
// 1. Content Header {
.region-content-top {
    box-shadow: 0 3px 6px rgba(0, 0, 0, 0.3);
    
    &>.mx-scrollcontainer-wrapper {
        display: flex;
    }
}

// 1.1 Filter section
.wms-div-iconfilter {
    background-color: $gray-lighter;
    height: $wms-header-height;
    padding-top: 20px;
    border-bottom: 1px #dcdcdc solid;
    min-width: 350px;

    .simple-wipmain-buttonIn > input[type="text"] {
        height: 2em;
        font-size: 15px;
        margin: 0px;
        margin-top: auto;
        margin-bottom: auto;
    }

    .simple-wipmain-buttonIn {
        position: relative;
    }

    .simple-wipmain-buttonIn > input[type="button"] {
        position: absolute;
        background: url('img\cmdCloseTab16.svg') no-repeat center center;
        height: 2em;
        width: 30px;
        cursor: pointer;
        color: transparent;
        right: 0px;
        z-index: 2;
        border: none;
        display: none;
    }
    .row div {
            padding-left: 1px;
            padding-right: 1px;
            .wms-btn-filter
            {
                width: 100%;
                .glyphicon {
                    color: transparent;
                    background-repeat: no-repeat;
                    font-size: 20px;
                    margin-right: 0.2rem;
                    top: 3px;
                }

                .dropdown-toggle {
                    display: block;
                    border: none;
                    box-shadow: none;
                    padding: 7px 2px;
                    width: 100%;
                    font: normal normal 600 12px/16px Segoe UI;
                    color: $font-color-default;
                    text-overflow: ellipsis;
                    overflow: hidden;
                    background: transparent;
                    &:hover {
                        box-shadow: none;
                    }
                }

                .caret {
                    display: none;
                    border: none;
                }

                .dropdown-menu {
                    padding: 0px;
                    min-width: 120px;

                    .mx-layoutgrid-fluid {
                        background: #FFFFFF 0% 0% no-repeat padding-box;
                        box-shadow: 0px 3px 6px #0000004D;
                        border: 1px solid #DCDCDC;
                        border-radius: 3px;
                        opacity: 1; 
                    }
                    div {
                        padding: 0px;
                    }
                    .row {
                        margin: 0px;                        
                        button {
                            border: none !important; 
                            width: 100%;
                            color: $font-color-default;
                            text-align: left;
                            box-shadow: none;
                            padding: 8px 8px 8px 8px;
                            font: normal normal normal 12px/16px Segoe UI;
                        }
                        button:focus {
                            outline: none;                
                        }

                        button.selected {
                            background-color: #DAECF0;               
                        }
                        img {
                            margin: 0px 4px 4px 0;
                            filter: none;
                            width: 16px;
                            height: 16px;
                        }
                    }
                }
            }

            .mx-name-ddReadyFor {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_All$cmdNextRequired16.svg');
                }
            }

            .MoveIn {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorMoveIn16.svg');
                }
            }

            .TrackIn {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorInputIntended16.svg');
                }
            }

            .TrackOut {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorOutputIntended16.svg');
                }
            }

            .MoveOut {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorMoveOut16.svg');
                }
            }

            .mx-name-ddAvailability {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_All$cmdCheckConsistency24.svg');
                }
            }

            .Available {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_All$indicatorStatusReady16.svg');
                }
            }

            .Non_Available {
                .glyphicon {             
                    background-image: url('img/EXSM_WIPMainSimple$Image_All$indicatorStatusStopped16.svg');
                }
            }

            .mx-name-ddExpandCell {
                border: none;
                padding: 8px 2px 0 2px;
                max-width: 110px;
                font: normal normal 600 12px/16px Segoe UI;
                color: $font-color-default;
                background: transparent;
                box-shadow: none;
                img {
                    height: 20px;
                    margin-top: -2px;
                    filter: none;
                }
            }

            .mx-name-ddExpandCell:focus {
                outline: none !important;                
            }

            .expandcell-collapse > img {
                content: url('img/EXSM_WIPMainSimple$Image_All$cmdCollapseBelow16.svg');
            }
            
        }
    
}


//1.2 Text Filter
.wms-div-textfilter{
    background-color: $gray-lighter;
    height: $wms-header-height;
    max-width: 100%;
    border-bottom: 1px #dcdcdc solid;
    padding-top: 5px;

    .row {
            padding-right: 10px;            
            .wms-col-textfilter{
               padding-left: 8px;
               padding-right: 8px;  
            }
            .wms-textboxfilter > input[type="text"]{
                padding: 8px;
                &:placeholder-shown {
                    font-style: italic;
                }

            }
            div.inner-btn {
                position: absolute;
                right: 1px;
                top: 4px;
               .mx-link{
                   display: inline-block;
                   padding: 0px;
                   img {
                        margin-bottom: 2px;
                   }
                }
                .wms-clearbutton {
                    display: inline;
                    padding: 4px 8px 7px 8px;
                }
                .wms-searchbutton {
                    display: inline;
                    padding: 4px 8px 7px 8px;
                }
                .wms-clearbutton:hover, .wms-searchbutton:hover{
                    background-color: $wms-hover-color;
                }
            }

        .col {
                .mx-layoutgrid {
                    padding-right: 0px;

                .wms-clearbuttonDiv {
                    padding-left: 5px;
                    .wms-clearbutton{
                        right:80px;
                    }
                }
            }
        }

        .wms-clearbutton-div {
            padding: 0 5px 0 5px;
            max-width: 20px;
        } 
         .wms-clearbuttonall{
            padding: 0;
            line-height: 25px;
           margin-top: 4px;
        }    
          
    }
}

// 2. Left Sidebar
.wms-side-left {
    min-width: 330px;
    background-color: transparent !important;
    border-right: none !important;
    &> div:first-child {
        overflow: hidden !important;
    }
    .mx-dataview-content {
        overflow-x: hidden !important;
    }
}


