// 2.1 Dispatch List Label Region
.loading-label {
    width: 100%;
    color: #0f789b;
    text-align: center;
}
.dispatchlist-label-region{
    z-index: 1;

    .datagrid-options {
        padding: 0 0 0 0.5px;
        margin: 0px;
    }

    .dispatchlist-count {
        background-color: #E3FAFF;
        border: 1px solid #66C8DE;
        border-radius: 3px;
        margin: 4px 0px 2px 1px;
        padding: 0 8px;

        .dispatchlist-label {
            margin-bottom:0px;
            min-height:35px;
            padding-top: 8px;
            color: rgb(37, 150, 190);
            
        }       
    }       
}

// 2.2 Dispatch Lot List
.wms-div-dispatchlist {
    .dispatchlist-icon-first{
        padding: 8px 8px 0 8px;
        .container-checkbox {
            position: absolute;
            .mx-checkbox > div[class*=col-] {
                margin: 0px;
                padding: 0px !important;
            }
            input {
                background-color: white;
                &:checked {
                    background-color: #197fa2;
                }
            }
        }
    }

    .icon-first{
        height: 48px;
    }

    .dispatchlist-wipstateicon{
        padding: 0px;
        //max-width: 30px;
    
        .btn-wipstate{
            
            padding: 0px;
        }
        .btn-wipstate > img{
            width: 16px;
            height: 16px;
            vertical-align: middle;
        }

        .carrierTooltip {
            margin-left: 4px;
            display: inline-block;
            .carriersInfo{
                text-align: left;
                .clabel {
                    content: "Carriers: ";
                    font: normal normal bold 12px/16px Segoe UI;
                }
            }
            .batchNoInfo{
                text-align: left;
                span.mx-text:before{
                    content: "Batch No: ";
                    font: normal normal bold 12px/16px Segoe UI;
                }
            }
            .widget-tooltip-content {
                position: fixed !important;
                max-width: 250px;

            }
            .mx-text {
                max-width: 100px;
            }
            .imgDiv {
                img {
                    width: 24px;
                    height: 24px;
                }
            }
            
            
        }
    }

    .dispatchlist-body {
        padding: 8px;
        .qtyImg {
            margin: 0 auto;
            padding: 0 0 0 8px;
        }
    }

    .dispatchlist-prioritycode-region{
        align-self: center;
        margin-left: 8px;
        max-width: 140px;
        padding: 2px 4px 0 0;

        a:focus, a:hover {
            text-decoration: none;
        }

        .dispatchlist-prioritycode{
            padding: 2px 8px;
            color: white;
            text-align: center;
            font: normal normal 600 12px/16px Segoe UI;
            background: #005F87 0% 0% no-repeat padding-box;;
            border: 1px solid #003951;
            border-radius: 12px;
            height: 24px;
            align-self: center;
            vertical-align: top; 
        }
    }

    .mx-listview li,.mx-listview li:last-child {
        border: none;
        background-color: transparent;
        margin-top : 1px;
    }

    .mx-listview{
        .selected {
            .dispatchListTiles {
                background-color: $wms-hover-color !important;
            }
        }
        
    }
    .dispatchListTiles  {
        font-size: 14px;
        background-color: #f0f0f0;

        .mx-name-LotName {
            margin-bottom: 0;
        }
        &:hover:not(:has(.parenthover:hover)) {
            background-color: $wms-hover-color;
        }

         
         .container-checkbox {
             .form-group {
                padding-top: 0px !important;
             }
             label {
                padding-left: 0px !important;
            }
        }
        .dispatchlist-lot-detail {
            padding: 0px;
            display: flex;
            justify-content: flex-end;
            .lotinfo-icon {
                width: 40px;
                height: 40px;
                float: right;
                &:hover {
                    border: $wms-hover-border;
                    background-color: $wms-hover-color;
                }
                img {
                    margin:  5px auto;

                }
            }
            .activity-status-icon {
                width: 40px;
                height: 40px;
                float: right;
                img {
                    margin:  5px auto;

                }
            }
        }
        
    }

    .onhold {
        border-left: 4px solid #bf1b1b !important;
    }

    li.mx-listview-empty{
        margin-top: 50%;
        display: flex;
        justify-content: center;
        border: none;

        &::before{
            content: url('img/EXSM_WIPMainSimple$Image_All$No_Data_Image.png');
            transform: scale(0.5, 0.5);
            opacity: 0.35;
        }
        &::after{
            content: $wms-empty-message-custom;
            position: absolute;
            align-self: flex-end;
            height: 35px;
        }
        label{
             display: none;
             opacity: 0.8;
        }
    }
    

}


// 3. Working section
.wms-working-ctr {
    .mx-scrollcontainer-center >  {
        .mx-scrollcontainer-wrapper {
            overflow-y: hidden;
        }
    }

    /*Dynamic value - Rewrite style value on own styling file*/   
    // Remove border line for the collapse section
    .mx-groupbox {
        margin: 0;
        border: none;
        box-shadow: none;
        &:hover {
            box-shadow: none;
        }
        .mx-groupbox-header {
            background-color: #f5f7fa;
        }
    }
}

// 3.1 Equipment List section
.wms-div-equipmentList {
    div.mx-name-Equipment {
        overflow: auto;
        white-space: nowrap;
        cursor: pointer;
        &.spacing-outer-right {
            margin: 0 5px 0 0 !important;
        }
    }
   
     .mx-listview li {
        background-color: transparent;
        
    }
    .mx-name-GridEqpsection:hover {
        background-color:$wms-hover-color;
    }

    .mx-name-GridEqpsection.selected {
        background-color: $wms-hover-color;                
    }

    li.mx-listview-empty{
        opacity: 0.8;
        margin: auto;
        display: flex;
        justify-content: center;
        &::before{
            //content: url('img/EXSM_WIPMainSimple$Image_All$No_Data_Image.png');
            //transform: scale(0.6, 0.7);
        }
        &::after{
            content: $wms-empty-message-custom;
            position: absolute;
            align-self: flex-end;
            height: 35px;
        }
        label{
             display: none;
        }
    }
   
   
    ul > li {
        display: inline-block;
    }

    .equipmentListView{
        overflow-x: auto;     
        white-space: nowrap;
        padding: 0 5px;

        li {
            border: none;
        }
        
    }

    .equipmentListTile{
        background-color: transparent;
        .mx-text{
            white-space: nowrap;
        }
    }

    .eqp-icon-col{
        display: flex;
        .info-icon{
            padding-top: 1px;
            padding-right: 1px;
        }
        .eqp-icon{
            margin-left: auto;
            margin-right: auto; 
        }
    }

    .eqp-availabilityicon-col{
       
        padding-right: 5px;

       .eqp-availabilityicon{
           width: 15px;
           padding:0px;
        }
        
    }  
}

// 3.2 Collaspe Section
.wms-middle-section {
    .mx-scrollcontainer-wrapper {
        padding-left: 5px;
        min-height: 300px;
    }
    .mx-name-ProcessWP {
        margin-bottom: 0px;
        .mx-groupbox-body {
            padding: 10px 0 0 0;
        }
    }
    
    // dropdown
    //default
    .css-yt9ioa-option {
        background-color: transparent;
        color: inherit;
    }

    //selected
    .css-9gakcf-option {
        // background-color: #2684FF;
        // color: hsl(0, 0%, 100%);
        background: rgba(205,230,235,255);
        color: inherit;
    }

    //focus
    .css-1n7v3ny-option {
        background-color: #DEEBFF;
        color: inherit;
    }
}

// Begin Vertical Command Bar
.mx-name-commandBarContainer {
    position: relative;

    background-color: #f0f0f0;
    border-color: #dcdcdc;
    box-shadow: -1px 0 2px #dcdcdc;
    border-left-width: 1px;
    height: calc(100% - 4px);
    overflow: hidden;
    margin-top: 4px;

    .mx-name-cmdContainerTop {
        position:relative;
        height: calc(100% - 50px);
        z-index:1;
    }

    .mx-name-cmdContainerExpand {
        background-color: #f0f0f0;
        border: solid rgba(0,0,0,.3) 2px;
        position:absolute;
        height: auto;
        bottom: 50px;
        z-index:2;
        display: none;
        max-height: calc(100vh / 1.5);
        overflow: auto;

        .show {
            display: block;
        }
    }

    .mx-name-cmdContainerEnd
    {
        position:relative;
        bottom:0px;
        height:50px;
        width: 100%;
        text-align: center;
        z-index:3;
        background-color: #f0f0f0;

        &:hover {
            background-color: $wms-hover-color;
        }

        .mx-name-cmdDownButton {
            margin-left: 35%;
            width: 25px;
            height: 25px;

            .show {
                img {
                    content: url('img/EXSM_WIPMainSimple$Image_All$cmdCollapseBelow16.svg');
                }
            }
        }
    }

    .command-bar-action {
        padding: 12px 5px;
        transition: 0.2s;
    }

    .mx-text {
        text-align: center;
    }

}
// End Vertical Command Bar

// 3.2.1 Process Section
.wms-div-Process {
    flex-wrap: nowrap;
    background-color:white;
    width: 100%;

    .row > .col {
        min-width: 220px;
        flex-grow: initial;
    }

    input[type="text"]{
        max-width: 220px;
    }

    .wms-div-midColumn{
        display: inline-flex;
        flex-grow: 1 !important;
        .col-sm-offset-3 {
            margin-left: 0px;
            flex-basis: 100%;
            max-width: 350px;

            label {
                text-align: left;
            }
        }
    }
}


// 3.2.2 Activity Collapse Section
$accordion-header-height:60px;
$indicator-img-size:15px / 36px 25px;
$status-img-size: 24px;
$icon-size :30px / 30px 16px;
.mx-name-GBActivities { 
    flex-wrap: nowrap;
    background-color:white;
    width: 100%;  

    h1 {
        background: #FFFFFF 0% 0% no-repeat padding-box;
    }

    &.mx-groupbox {
        border-radius: 0.1875rem;
        border: $wms-hover-border;
        margin-right: 8px;
        
        &.collapsed {
            border: 2px solid #DCDCDC;
        }
    }

    /* Banner Headder Section Image and StyleSection Start */
    &.MoveIn
        {
            .mx-groupbox-header {
            background:  $icon-size no-repeat url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorMoveIn16.svg');
            //background-color: #f5f7fa;
            } 
        }
    &.TrackIn
        {
            .mx-groupbox-header {
            background:  $icon-size no-repeat url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorInputIntended16.svg');
            //background-color: #f5f7fa;
            } 
        }
    &.TrackOut
        {
            .mx-groupbox-header {
            background:  $icon-size no-repeat url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorOutputIntended16.svg');
            //background-color: #f5f7fa;
            } 
        }   
    &.MoveOut
        {
            .mx-groupbox-header {
            background:  $icon-size no-repeat url('img/EXSM_WIPMainSimple$Image_WIPTxn$indicatorMoveOut16.svg');
            //background-color: #f5f7fa;
            } 
        }
    /* Banner Headder Section Image and StyleSection End */
       
       
    input[type="text"]{
        //max-width: 220px;
        height: auto !important;
    } 

    // 3.2.2.1 Activities List
    .mx-name-ListViewActivitySection
    {
        .mx-name-ActivitiesSection
        {
            border: 0.5px solid rgba(0, 0, 0, 0.2);
            border-radius: 0.1875rem; 
            .imgnewpage
            {
                width: 22px;
                height: 22px;
            }
            .mx-link img,
            .mx-button img {
                height: 22px;
            }
            .mx-link {
                padding: 0px 0px;
                display: inline-block;
            }
            .mx-name-actDownButton {

                img {
                        content: url('img/DISW_DesignSystem$SVG_Icons$siemens_triangle_right.svg');
                    }

                &.show {
                    img {
                        content: url('img/DISW_DesignSystem$SVG_Icons$siemens_triangle_down.svg');
                    }
                }
            }
            .widget-accordion-group-content {
                padding: 10px 0 0 0;

                    .wms-div-midColumn{
                        display: inline-flex;
                        flex-grow: 1 !important;
                        .col-sm-offset-3 {
                            margin-left: 0px;
                            flex-basis: 100%;
                            max-width: 350px;
                            
                            label {
                                text-align: left;
                            }
                         }

                        }
            }   

            .widget-accordion-expandIcon {
                display: block;
                margin: auto;
            }

            .widget-accordion-actTitle {
                padding: 8px 0;
            }
            .ActivityTiles{
                border-radius: 0.1875rem;
                .title-lbl {
                    font-style: normal;
                    font-weight: 600;
                } 
                .status-lbl {
                    font-style: normal;
                    font-weight: 400;
                }
                              
            }

            .NoStatus {
                .ActivityTiles{
                    border-left: 4px solid #f0f0f0; 
                              
                }
               .widget-accordion-group {
                    min-height: 32px;
                } 
            }
            .Optional
            { 
                .ActivityTiles{
                    border-left: 4px solid #006487;
                    background-color: #e9fbff;        
                }
               .widget-accordion-group {
                    background: right 8px center no-repeat url('img/EXSM_WIPMainSimple$Image_All$indicatorOption16.svg') #e9fbff;
                    background-size: $status-img-size;
                } 
                            
            }
            .Passed
            {
               
               .ActivityTiles{
                    border-left: 4px solid #288722;
                    background-color: #f0fdf6;
                }
                .widget-accordion-group {
                    background: right 8px center no-repeat url('img/EXSM_WIPMainSimple$Image_All$indicatorCheckmarkGreen16.svg') #f0fdf6;
                    background-size: $status-img-size;
                }  
            }
            .NotExecuted
            {
                .ActivityTiles{
                    border-left: 4px solid #FFCD50;
                    background-color: rgba(255, 247, 205, 0.45);                    
                }
               .widget-accordion-group {
                    background: right 8px center no-repeat url('img/EXSM_WIPMainSimple$Image_All$indicatorWarning16.svg') rgba(255, 247, 205, 0.45);
                    background-size: $status-img-size;
                }             
            }
            .Incomplete
            {
                .ActivityTiles{
                    border-left: 4px solid #FF0000;
                    background-color: #ffeae9;                    
                }
                .widget-accordion-group {
                    background: right 8px center  no-repeat url('img/EXSM_WIPMainSimple$Image_All$indicatorError16.svg') #ffeae9;
                    background-size: $status-img-size;
                }
            }
            .WaferSelected
            {
               
               .ActivityTiles{
                    border-left: 4px solid #288722;
                    background-color: #f0fdf6;
                }
                .widget-accordion-group {
                    background: right 8px center no-repeat url('img/EXSM_WIPMainSimple$Image_All$indicatorCheckmarkGreen16.svg') #f0fdf6;
                    background-size: $status-img-size;
                }  
            }
            .WafersNotSelected
            {
               .ActivityTiles{
                    border-left: 4px solid #FFCD50;
