    color: #005F87;
}
.infoBar-warning-title{
    color: #B64C24;
}
.wms-infoBar {
    width: 100%;
    height: inherit;
    min-height: 32px !important;
    border-radius: 3px;
    opacity: 1;

    .wms-infoBar-right-section{
        width:100%;
        padding-right: 16px;

