// 4 Command Bar Content
    // 4.1 Slide Out Design
    &.modal-dialog-slideout{
        padding-top: 80px !important;
        height:100%;
        width: auto !important;

        .slideout-body {
            height: 100%;
            .slideout-column {
                width: $wms-slideout-min-width;
            }
            .slideout-column2 {
                width: calc($wms-slideout-min-width * 2);
            }
            .slideout-column3 {
                width: calc($wms-slideout-min-width * 3);
            }
        }
        
    }

    // 4.2 Alert Message Slide Out
    .alert-message-slideout {
        padding-top: 80px !important;
        height:100%;
        width:25%;
    }

    // 4.3 Alert Message Content
    .wms-alert-msg-list {
        .mx-name-listView1 ul li {
            width: 100% !important;
            border: 0px;
        }

        .wms-alert-msg-main {
            padding: 10px;
            width:100%;

            //Alert Message box content 
            .alert-message-box-content {
                width: 100%;
                height: inherit;
                // background: #FFF7CD 0% 0% no-repeat padding-box;
                // border: 1px solid #FFC328;
                border-radius: 3px;
                opacity: 1;

                .wms-alert-msg-top {
                    display: flex;
                    .wms-alert-msg-info-icon {
                        margin-top:8px;
                        margin-right:7px;
                    }
                    .wms-alert-msg-title {
                        margin-top:3px;
                        text-align: left;
                        font: normal normal bold 12px/26px Segoe UI;
                        letter-spacing: 0px;
                        // color: #B64C24;
                        padding-right: 3px;
                    }
                }

                .wms-alert-msg-btm {
                    .wms-alert-msg-message {
                        margin-top:3px;
                        text-align: left;
                        font: normal normal normal 12px/26px Segoe UI;
                        letter-spacing: 0px;
                        color: #464646;
                    }        
                }
            }
        }
    }

    // 4.4 Lot Details Slide Out
    .cmd-lotdetail-main {
        .lot-detail-left{
            padding-right: 8px;
        }
        .lot-detail-right{
            padding-left: 8px;
        }
    }

    // 4.5 Online Traveler Slide Out
    .cmd-onlinetraveler-main {
        min-width: calc($wms-slideout-min-width * 3);
        height: 100%;
        .back-btn {
            display: flex;
            height: 34px;
            width: auto;
            align-items: center;
            margin: 8px 0;
            padding: 4px 0;
            label {
                margin-left: 8px;
                padding-top: 4px;
            }
        }
        .toolbarGrid {
            padding: 8px 0;
            margin-top: 8px;
            border-top: 0.5px solid rgba(0, 0, 0, 0.2);
        }
        .sequence-column {
            padding: 0px;
            img {
                width: 16px;
                height: 16px;
            }
        }
        .content-table {
            td {
                padding: 2px 4px;
                border: none;
            }
        }
        .snip-banner {
            margin-top: 8px;
            margin-bottom: 8px;
            border-bottom: 0.5px solid rgba(0, 0, 0, 0.2);
        }
    }

    // 4.6 WIP Failures Slide Out
    .cmd-wiplimits-main {
        min-width: calc($wms-slideout-min-width * 3);
        height: 100%;
        .cat-row {
            margin: 16px 0;
            padding-bottom: 16px;
            border-bottom: 0.5px solid rgba(0, 0, 0, 0.2);
        }
        .cat-container {
            padding: 20px;
            border: 0.5px solid rgba(0, 0, 0, 0.2);
            max-height: 100px;
            width: 20%;
            flex: none;

            &.selected {
                background-color: #005f87;
                .cat-img {
                    .mx-text {
                        color: white;
                    }
                }
            }
            .cat-count {
                position: absolute;
                right: 5px;
                top: 5px;
                border-radius: 15px;
                background-color: #CDE6EB;
                font-size: 12px;
                font-weight: bold;
                padding: 4px 8px;
            }
            .cat-img {
                text-align: center;
                img {
                    width: 42px;
                    height: 42px;
                    display: block;
                    margin-left: auto;
                    margin-right: auto;
                }
            }
        }
        .refresh-btn {
            width: 90px;
        }
        .failuretype-column {
            padding: 0px;
            img {
                width: 16px;
                height: 16px;
            }
        }
    }

    // 4.7 Equipment Info Slide Out
    .cmd-eqpinfo-main {
        .mx-groupbox {
            border: none;
            margin: 0 0 16px 0;
            .mx-groupbox-header{
                background-color: #f5f7fa;
            }
        }
        .groupbox-main{
            .mx-groupbox-body{
                padding: 8px 0;
            }
        }
        .eqpinfo-body {
            max-width: 230px;
        }
    }

    // 4.9 SPC Chart
    .cmd-spcannotation-main {
        .subgroup-view { width: calc($wms-slideout-min-width * 2);}
        .dataview-view { width: calc($wms-slideout-min-width * 2.6);}
    }

