.datagrid-options {
    display: flex;
    border-bottom: 1px solid #DCDCDC;
    margin: 4px 0px;
    padding: 4px 0px;
    .command-button { //grid toolbar
        display: flex;
        padding: 9px 4px;
        align-items: center;


        &.standalone {
            border: 1px solid #828282;
            border-radius: 2px;
            height: 32px;
            min-width: 0;
            padding: 6px 12px;
            text-align: left;
            font: normal normal 600 10px/14px Segoe UI;
            letter-spacing: 0px;
            color: #464646;
            background: #FFFFFF 0% 0% no-repeat padding-box;

            &:hover {
                background: #DAECF0 0% 0% no-repeat padding-box;            
            }

            &:focus-within {
                background: #CDE6EB 0% 0% no-repeat padding-box;
                border: 2px solid #0F789B;
            }

            &:active {
                background: #CDE6EB 0% 0% no-repeat padding-box;
                border: 1px solid #828282;
            }



            .disabled-select {
                background: #00000012 0% 0% no-repeat padding-box;
                border: 1px solid #6E6E6E91;
                opacity: 1;
            }
        }

        .mx-text {
            max-width: 60px;
        }

        img {
            height: 16px;
            cursor: pointer;
            margin-right: 4px;
        }

        &:hover {
            background:  #DAECF0 0% 0% no-repeat padding-box;
            opacity: 1;
        }

        &:active {
            background: #CDE6EB 0% 0% no-repeat padding-box;
        }

        &.selected {
            background: #CDE6EB 0% 0% no-repeat padding-box;
            border: 2px solid #0F789B;
            opacity: 1;
        }
    }
}

// Accordion icon button styling 
.actIcon-btn {
    border-radius: 5px;
    border: 1px solid #205e86;
    width: 40px;
    height: 40px;
    display: inline-block;
    margin-left: 8px;

    &:hover {
        background-color: #CDE6EB;
    }

    img {
        margin: 8px;
        max-width: 24px;
        max-height: 24px;
        filter: invert(29%) sepia(22%) saturate(1925%) hue-rotate(162deg) brightness(95%) contrast(84%);
    }
}


