/*datagrid 2 header not overflow*/
.ux-table.table-header-not-overflow {
    .table .th .column-header span{
        text-overflow: unset;
        overflow: unset;
    }
    .mx-checkbox{
        padding-top: 0px !important;
    }
}

/*datagrid 2 header not overflow*/
.table-header-remove {
    .table .th {
        display: none;
    }
}

.dv-padding-remove {
    .mx-dataview-content {
        padding-top: 0 !important;
    }
}

/*material setup datagrid 2 header option adjustment*/
.dg-header-adjustment {
    height:45px;

    .mx-checkbox > div[class*=col-] {
        flex-wrap: nowrap !important;
        min-width: fit-content;
    }

    .cmd-checkbox {
        align-self: center;
        padding-left:4px;
        padding-right:4px;
        .mx-checkbox {
            padding-bottom: 9px;
            padding-top:9px !important;
        }
    }

    .cmd-switch {
        display: flex;
        padding-top: 4px;
        .apply-font {
            padding-left: 15px;
            padding-top: 5px;
        }
    }
}

.asterisk-required::before{
