/* to disable datagrid2 content overflow to allow custom dropdown menu is not hidden */
.widget-datagrid-content {
    overflow-y: unset;
}

/* set auto width to input field in the datagrid2 */
.ux-table .table .tr .td .td-custom-content {
    flex-grow: 1;
}

.mx-textarea {
    
    &.form-group {
        margin-left: unset;
        margin-right: unset;
    }
    &.form-group.no-columns {
        padding-left: unset;
        padding-right: unset;
    }
}

/* fix the widget gallery list summary item append horizontal 
when media width screen getting smaller */
.widget-gallery .widget-gallery-items {
    grid-template-columns: unset !important;
    justify-content: unset !important;
}


