.wipActivity-page {
    .row > .col {
        input:not([type=checkbox]), select {
            //min-width: 220px;
        }
       //flex-grow: initial;       
    }

    //0. Start Binning Activity
    .mx-name-BinningContainer{
        .ctr-bindetails{
            padding: 16px 16px;
        }
        .mx-name-QtySection{
            .row > .col {
            input:not([type=checkbox]), select {
                min-width: 150px;
            }
            
            }
        }
        
    }
    //0. End Binning Activity

    //7. Material Setup Activity
    &.mx-name-MaterialActivity {
    .mx-name-MTRequiredGrid {
        margin-bottom: 16px;
        .mtr-header {
            td {
                padding: 8px 4px;
                background-color: #e6e6e6;
                border: 1px solid #dcdcdc;
                vertical-align: middle;
                .mx-text {
                    margin: 0;
                    //min-height: 100%;
                    color: #0a1325;
                    font-family: "Segoe UI", "selawik", "Open Sans", Arial, sans-serif;
                    font-size: 16px;
                }
            }
        }
        .mtr-content-list {
            li {
                margin: 0px;
                border-top: none;
                border-bottom: 1px solid #dcdcdc;
                border-left: 1px solid #dcdcdc;
                border-right: 1px solid #dcdcdc;
                .mtr-row {
                    tr {
                        border: none;
                    }
                    td:nth-child(1) {
                        padding: 0px;
                        img {
                            max-width: 24px;
                            max-height: 24px;
                            margin: auto;
                        }
                        .show {
                            img {
                                content: url('img/EXSM_DesignSystem$Images$miscDownArrow16.svg');
                            }
                        }
                    }
                    td {
                        height: 32px;
                        padding-left: 16px;
                        padding-right: 16px;
                        padding-top: 4px;
                        padding-bottom: 4px;
                        vertical-align: middle;
                        
                        color: #0a1325;
                        font-family: "Segoe UI", "selawik", "Open Sans", Arial, sans-serif;
                        font-size: 16px;
                        font-weight: normal;
                        line-height: 1.5;
                    }
                }
                .alternate-ctn {
                    padding: 0px 16px 0px 50px;
                }
                &:nth-child(even) {
                    background: #F0F0F0 0% 0% no-repeat padding-box;
                    opacity: 1;
                }
                &:nth-child(odd) {
                    background: #FFFFFF 0% 0% no-repeat padding-box;
                    opacity: 1;
                }
                &:hover {
                    background: #DAECF0 0% 0% no-repeat padding-box;
                    opacity: 1;
                } 
            }
            
        }
    }
    .mx-name-MTRDetailGrid.ux-table {
        .mx-button {
            box-shadow: none;
        }
        .table-content {
            overflow: hidden;
            overflow-x: auto;
        }
        .th:nth-of-type(2),.th:nth-of-type(3){
            min-width: 150px;
        }
        .th:nth-of-type(4){
            min-width: 90px;
        }
        .th:nth-of-type(10){ // vendor
            min-width: 180px;
        }
        .th:nth-of-type(12),.th:nth-of-type(13),.th:nth-of-type(14),.th:nth-of-type(15) { // date picker
            min-width: 250px;
        }
        
    }
    }
    //7. End Material Setup Activity

    //10.start  ItemsReject Activity
    &.mx-name-ItemRejectActivity{
          .control-label{
             font-weight: 600;
         }
         .col-lg.col-md.col.wms-div-midColumn {
             display: inline-flex;
            flex-grow: 0.3 !important;
            padding-left: 16px;
          

         }
        
         .mx-textbox-totalqty{
             max-width: 150px;
         }
        
    }
    //10.End Items Reject Activity

    //11. For Lot Reject Activity
    &.mx-name-LotRejectActivity {  
        .mx-name-LRJDetailGrid.ux-table {
            .mx-button {
                box-shadow: none;
            }
        }
    }

    //13. For AQL Sampling Activity
    &.mx-name-AQLSamplingActivity {
        .mx-name-SectionByLot, .mx-name-SectionByItemIds {
            padding: 0px 16px 0px 16px;
        }
        .wipdataname-required-lbl{
            color: #3296b9;
            pointer-events: none;
        }

        .wipdatavalue-txt {
            &.valueRequired {      
                &> input[type="text"].form-control{
                    &::placeholder {
                        font: italic normal normal 12px/16px Segoe UI;
                        letter-spacing: 0px;
                        color: #666666;
                        background: no-repeat left center / 10px 10px url('img/EXSM_DesignSystem$Images$indicatorMandatory16.svg');
                    
                    }
                }
            }
            &.warning > input[type="text"].form-control{
                background-color: #DC00001A;
                border: 1px solid #DC0000;
                &::placeholder {
                    font: normal normal 600 12px/16px Segoe UI;
                    color: #DC0000;
                    background: no-repeat left center / 10px 10px url('img/EXSM_DesignSystem$Images$indicatorMandatoryRed16.svg'), no-repeat right center padding-box url('img/EXCR_Commons$Images$indicatorWarningTriangleRed16.svg');
                }
            }
            &> input[type="text"].form-control{
                &:hover {
                    background: #FFFFFF 0% 0% no-repeat padding-box;
                    border: 2px solid #828282;
                }
                &:focus {

                    background: #FFFFFF 0% 0% no-repeat padding-box;
                    border: 2px solid #3296B9;
                    &::placeholder {
                        background: none;
                        color: transparent;
                    }
                }
            }
        }
        .validvalue-btn > img{ // WIP Data accordion By Lot and By Item IDs grid
            height: 30px !important;
            padding-top: 5px;
        }
    }
    //13. End for AQL Sampling Activity

    //16.Start ToolPlan Activity
    .wms-div-toolplan-params{
        padding: 0px;
    }
    //16.End ToolPlan Activity


    //17. For WIP Data Activity
    &.mx-name-WIPDataActivity {
        .mx-name-SectionByLot, .mx-name-SectionByItemIds {
            padding: 0px 16px 0px 16px;
        }
        .wipdataname-required-lbl{
            color: #3296b9;
            pointer-events: none;
        }

        .wipdatavalue-txt {
            &.valueRequired {      
                &> input[type="text"].form-control{
                    &::placeholder {
                        font: italic normal normal 12px/16px Segoe UI;
                        letter-spacing: 0px;
                        color: #666666;
                        background: no-repeat left center / 10px 10px url('img/EXSM_DesignSystem$Images$indicatorMandatory16.svg');
                    
                    }
                }
            }
            &.warning > input[type="text"].form-control{
                background-color: #DC00001A;
                border: 1px solid #DC0000;
                &::placeholder {
                    font: normal normal 600 12px/16px Segoe UI;
                    color: #DC0000;
                    background: no-repeat left center / 10px 10px url('img/EXSM_DesignSystem$Images$indicatorMandatoryRed16.svg'), no-repeat right center padding-box url('img/EXCR_Commons$Images$indicatorWarningTriangleRed16.svg');
                }
            }
            &> input[type="text"].form-control{
                &:hover {
                    background: #FFFFFF 0% 0% no-repeat padding-box;
                    border: 2px solid #828282;
                }
                &:focus {

                    background: #FFFFFF 0% 0% no-repeat padding-box;
                    border: 2px solid #3296B9;
                    &::placeholder {
                        background: none;
                        color: transparent;
                    }
                }
            }
        }
        .validvalue-btn > img{ // WIP Data accordion By Lot and By Item IDs grid
            height: 30px !important;
            padding-top: 5px;
        }
    }
    //17.End For WIP Data Activity
}
