// 20. Wafer Sampling
//wafer sampling activity 
.wafer-sampling-activity {
    .detected {
        color: #005F87;
        background: #C8F5FF 0% 0% no-repeat padding-box;
        border: 1px solid #005F87;
    }
    .not-detected {
        //color: #FFCD50;
        color: #005F87;
        //background: rgba(255, 247, 205, 0.45) 0% 0% no-repeat padding-box;
        background: #C8F5FF 0% 0% no-repeat padding-box;
        border: 1px solid #005F87;
        //filter: invert(0%) sepia(0%) saturate(0%) hue-rotate(0deg) brightness(100%) contrast(106%);
    }
    .wafer-sampling-method {
        width:fit-content;
        padding: 3px 8px;
        //color: #005F87;
        text-align: center;
        font: normal normal 600 12px/16px Segoe UI;
        //background: #C8F5FF 0% 0% no-repeat padding-box;
        box-shadow: 0px 1px 2px #0000004D;
        //border: 1px solid #005F87;
        border-radius: 12px;
        height: 24px;
        align-self: center;
        vertical-align: top;
    }
    .select-wafer-container {
        .mx-button img{
            height: 16px !important;
        }
        .mx-button {
            background: #FFFFFF 0% 0% no-repeat padding-box;
        }
    }
    .mx-name-listView1 ul li {
        margin-left: 0px !important;
    }
    .wafer-item-list {
        width: max-content;
        .wafer-item-tag {
            display: flex;
            width: max-content;
            padding: 3px 8px;
            //color: #005F87;
            text-align: center;
            font: normal normal 600 12px/16px Segoe UI;
            background: #FFFFFF 0% 0% no-repeat padding-box;
            box-shadow: 0px 1px 2px #0000004D;
            //border: 1px solid #005F87;
            border-radius: 12px;
            height: 24px;
            align-self: center;
            vertical-align: top;

            .wafer-item-name {
                padding-right: 8px;
            }
            .wafer-item-close {
                filter: invert(19%) sepia(97%) saturate(1697%) hue-rotate(176deg) brightness(99%) contrast(101%);
            }
        }
    }
    
}
// End Wafer Sampling


